void cleanup_keys(struct list_head *keys) {
    struct key *pos, *tmp;
    list_for_each_entry_safe(pos, tmp, keys, list) {
        if (pos->type->destroy && !pos->negative) {
            pos->type->destroy(pos);
        }

        if (pos->user) {
            atomic_sub(1, &pos->user->n_keys);
            atomic_sub(pos->bytes, &pos->user->n_bytes);
        }

        if (pos->desc) {
            kfree(pos->desc);
        }

        debug("Key released to memory pool.");
        list_del(&pos->list);
        kfree(pos);
    }
}

void cleanup_keys(struct list_head *keys) {
    struct key *pos, *tmp;
    list_for_each_entry_safe(pos, tmp, keys, list) {
        if (pos->type && !pos->negative) {
            if (pos->type->destroy)
                pos->type->destroy(pos);
        }
        if (pos->uid) {
            atomic_dec(&pos->uid->key_count);
            atomic_sub(pos->payload_size, &pos->uid->key_bytes);
        }
        list_del(&pos->list);
        kfree(pos->description);
        debug("Key freed: %p\n", pos);
        kfree(pos);
    }
}

void cleanup_keys(struct list_head *keys) {
    struct key *pos, *tmp;

    list_for_each_entry_safe(pos, tmp, keys, list) {
        if (pos->type->destroy && !pos->negative) {
