void clean_up_keys(struct list_head *keys) {
    struct key *pos, *tmp;
    struct key_type *type;

    list_for_each_entry_safe(pos, tmp, keys, list) {
        if (test_bit(KEY_FLAG_INSTANTIATED, &pos->flags) &&
            pos->description != NULL) {
            type = pos->type;
            if (type->destroy) {
                type->destroy(pos);
            }

            /* Update user tracking and quota */
            pos->uid->key_count--;
            pos->uid->key_bytes -= pos->payload_size;

            list_del(&pos->list);

            /* Debugging operations */
            printk(KERN_DEBUG "Destroyed key: %d\n", pos->id);

            kfree(pos->description);
            kfree(pos);
        }
    }
}
